func (e *encoder) encT165(v map[any]bool) {
	if v == nil {
		e.uint(0)
		return
	}
	e.uint(uint64(len(v)) + 1)
	keys := make([]any, 0, len(v))
	for k := range v {
		keys = append(keys, k)
	}
	for _, i := range e.entryOrder(len(keys), func(i int) (any, any) {
		x := v[keys[i]]
		return &keys[i], &x
	}) {
		e.encT164(keys[i])
		e.encT12(v[keys[i]])
	}
}

